'use strict';
// Every export goes to its own numbered subfolder of the output folder: Export/PubChem/1, 2, 3 …
const fs = require('fs');
const path = require('path');

/** Creates and returns <dir>/<n>, n = highest numbered subfolder + 1 (existing folders are never reused) */
function newRunFolder(dir) {
  fs.mkdirSync(dir, { recursive: true });
  let n = 0;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) if (e.isDirectory() && /^\d+$/.test(e.name)) n = Math.max(n, Number(e.name));
  for (;;) {
    const run = path.join(dir, String(++n));
    try { fs.mkdirSync(run); return run; } catch (e) { if (e.code !== 'EEXIST') throw e; }
  }
}

module.exports = { newRunFolder };

