"use strict";
// Adding a tag to the notes picked in the search results (front matter "tags:").

/** "#Paper 2026" -> "Paper-2026"; null if it cannot be an Obsidian tag */
function normalizeTag(input) {
  const tag = String(input || "").trim().replace(/^#+/, "").replace(/\s+/g, "-");
  if (!tag || /^\d+$/.test(tag) || !/^[\p{L}\p{N}_\-/]+$/u.test(tag)) return null;
  return tag;
}

/** Adds the tag to a front-matter object (as Obsidian's processFrontMatter passes it). Returns true if added. */
function addTag(frontmatter, tag) {
  let tags = frontmatter.tags ?? frontmatter.tag;
  if (frontmatter.tag !== undefined && frontmatter.tags === undefined) delete frontmatter.tag;
  if (tags == null || tags === "") tags = [];
  else if (typeof tags === "string") tags = tags.split(/[,\s]+/).filter(Boolean);
  else if (!Array.isArray(tags)) tags = [String(tags)];
  tags = tags.map((t) => String(t).replace(/^#/, ""));
  const has = tags.some((t) => t.toLowerCase() === tag.toLowerCase());
  if (!has) tags.push(tag);
  frontmatter.tags = tags;
  return !has;
}

module.exports = { normalizeTag, addTag };

